float MinPlayer(const GTNode* node)
{
// If this is a leaf, return score
if (node->mChildren.empty())
{
return GetScore(node->mState);
}
// Find the subtree with the minimum value
float minValue = std::numeric_limits<float>::infinity();
for (const GTNode* child : node->mChildren)
{
minValue = std::min(minValue, MaxPlayer(child));
}
return minValue;
}
Calling MaxPlayer on the root node returns the best possible score for the max player. How-
ever, this doesn’t specify which next move is optimal, which the AI player also wants to know.
The code for determining the best move is in a separate MinimaxDecide function, given in
Listing 4.6. MinimaxDecide resembles the MaxPlayer function, except it tracks which child
yields the best value.
Listing 4.6 MinimaxDecide Implementation
const GTNode* MinimaxDecide(const GTNode* root)
{
// Find the subtree with the maximum value, and save the choice
const GTNode* choice = nullptr;
float maxValue = -std::numeric_limits<float>::infinity();
for (const GTNode* child : root->mChildren)
{
float v = MinPlayer(child);
if (v > maxValue)
{
maxValue = v;
choice = child;
}
}
return choice;
}
