~AudioComponent();
void Update(float deltaTime) override;
void OnUpdateWorldTransform() override;
SoundEvent PlayEvent(const std::string& name);
void StopAllEvents();
private:
std::vector<SoundEvent> mEvents2D;
std::vector<SoundEvent> mEvents3D;
};
