{
const float deadZone = 8000.0f;
const float maxValue = 30000.0f;
// Make into 2D vector
Vector2 dir;
dir.x = static_cast<float>(inputX);
dir.y = static_cast<float>(inputY);
float length = dir.Length();
// If length < deadZone, should be no input
